def get_station_by_id(station_id: str) -> dict | None:
    """Get a single station by ID."""
    for station in TOLEDO_STATIONS:
        if station['id'] == station_id:
            return station
    return None


def get_all_stations(brand_filter: str | None = None) -> list:
    """Get all stations, optionally filtered by brand."""
    if not brand_filter:
        return TOLEDO_STATIONS
    if brand_filter.lower() == 'repsol':
        return [s for s in TOLEDO_STATIONS if s.get('brand') == 'Repsol']
    return [s for s in TOLEDO_STATIONS if s.get('brand') == brand_filter]


def count_stations(brand: str | None = None) -> int:
    """Count stations, optionally by brand."""
    if not brand:
        return len(TOLEDO_STATIONS)
    return len(get_all_stations(brand))
